//Generated by an LLM, Reviewed
#include "Ssdt/Ssdt.h"
#include "Msr/MsrControlField.h"
#include "Log/Log.h"
#include <intrin.h>

PSYSTEM_SERVICE_TABLE Ssdt::ServiceTable = NULL;
BOOLEAN Ssdt::Initialized = FALSE;

BOOLEAN
Ssdt::Initialize()
{
	if (Ssdt::Initialized && Ssdt::ServiceTable != NULL)
	{
		return TRUE;
	}

	Ssdt::ServiceTable = Ssdt::FindSsdtTable();
	if (Ssdt::ServiceTable == NULL)
	{
		LogError("Failed to locate KeServiceDescriptorTable (SSDT)");
		return FALSE;
	}

	Ssdt::Initialized = TRUE;
	LogInformation("SSDT located successfully at %p (Services Count: %llu, TableBase: %p)",
		Ssdt::ServiceTable,
		Ssdt::ServiceTable->NumberOfServices,
		Ssdt::ServiceTable->ServiceTableBase);

	return TRUE;
}

PSYSTEM_SERVICE_TABLE
Ssdt::GetTable()
{
	if (!Ssdt::Initialized)
	{
		Ssdt::Initialize();
	}

	return Ssdt::ServiceTable;
}

PVOID
Ssdt::GetFunctionAddress(ULONG SystemServiceNumber)
{
	if (!Ssdt::Initialized)
	{
		if (!Ssdt::Initialize())
		{
			return NULL;
		}
	}

	if (Ssdt::ServiceTable == NULL || SystemServiceNumber >= Ssdt::ServiceTable->NumberOfServices)
	{
		LogError("Invalid SystemServiceNumber: 0x%X (Max: %llu)",
			SystemServiceNumber,
			Ssdt::ServiceTable ? Ssdt::ServiceTable->NumberOfServices : 0);
		return NULL;
	}

	// On x64 Windows, ServiceTableBase contains 32-bit signed offsets.
	// Low 4 bits are argument flags; arithmetic right shift by 4 recovers relative offset.
	LONG Offset = (LONG)Ssdt::ServiceTable->ServiceTableBase[SystemServiceNumber];
	PVOID FunctionAddress = (PVOID)((PUCHAR)Ssdt::ServiceTable->ServiceTableBase + (Offset >> 4));

	return FunctionAddress;
}

ULONG
Ssdt::GetServiceCount()
{
	if (!Ssdt::Initialized)
	{
		if (!Ssdt::Initialize())
		{
			return 0;
		}
	}

	return (ULONG)(Ssdt::ServiceTable ? Ssdt::ServiceTable->NumberOfServices : 0);
}

BOOLEAN
Ssdt::ValidateSsdt(PSYSTEM_SERVICE_TABLE Table)
{
	if (!Table || !MmIsAddressValid(Table))
	{
		return FALSE;
	}

	// Windows x64 SSDT typically has 300 to 2000 service entries
	if (Table->NumberOfServices < 300 || Table->NumberOfServices > 2000)
	{
		return FALSE;
	}

	if (!Table->ServiceTableBase || !MmIsAddressValid(Table->ServiceTableBase))
	{
		return FALSE;
	}

	// Validate the 1st entry (Index 0)
	LONG Offset0 = (LONG)Table->ServiceTableBase[0];
	PVOID Func0 = (PVOID)((PUCHAR)Table->ServiceTableBase + (Offset0 >> 4));
	if (!MmIsAddressValid(Func0))
	{
		return FALSE;
	}

	// Validate the 10th entry (Index 10) to confirm validity
	LONG Offset10 = (LONG)Table->ServiceTableBase[10];
	PVOID Func10 = (PVOID)((PUCHAR)Table->ServiceTableBase + (Offset10 >> 4));
	if (!MmIsAddressValid(Func10))
	{
		return FALSE;
	}

	return TRUE;
}

ULONG_PTR
Ssdt::GetKernelBase(PVOID KnownKernelAddress)
{
	if (!KnownKernelAddress)
	{
		return 0;
	}

	ULONG_PTR Address = (ULONG_PTR)KnownKernelAddress & ~(PAGE_SIZE - 1);

	// Search backwards page by page for PE header (up to 64MB)
	for (ULONG Page = 0; Page < 0x4000; Page++, Address -= PAGE_SIZE)
	{
		PIMAGE_DOS_HEADER Dos = (PIMAGE_DOS_HEADER)Address;
		if (MmIsAddressValid(Dos) && Dos->e_magic == IMAGE_DOS_SIGNATURE)
		{
			if (Dos->e_lfanew > 0 && Dos->e_lfanew < 0x1000)
			{
				PIMAGE_NT_HEADERS Nt = (PIMAGE_NT_HEADERS)(Address + Dos->e_lfanew);
				if (MmIsAddressValid(Nt) && Nt->Signature == IMAGE_NT_SIGNATURE)
				{
					return Address;
				}
			}
		}
	}

	return 0;
}

PSYSTEM_SERVICE_TABLE
Ssdt::FindSsdtTable()
{
	// 1. Read IA32_LSTAR MSR (0xC0000082) -> points to KiSystemCall64 or KiSystemCall64Shadow
	PUCHAR Lstar = (PUCHAR)__readmsr(IA32_LSTAR);
	if (!Lstar || !MmIsAddressValid(Lstar))
	{
		LogError("Failed to read IA32_LSTAR MSR");
		return NULL;
	}

	// Strategy 1: Fast scan forward from LSTAR (covers KiSystemCall64 and nearby stubs)
	for (ULONG i = 0; i < 0x2000; i++)
	{
		PUCHAR Ptr = Lstar + i;
		if (!MmIsAddressValid(Ptr) || !MmIsAddressValid(Ptr + 7))
		{
			break;
		}

		// Look for: 4C 8D 15 [disp32] (lea r10, [KeServiceDescriptorTable])
		if (Ptr[0] == 0x4C && Ptr[1] == 0x8D && Ptr[2] == 0x15)
		{
			LONG Disp = *(PLONG)(Ptr + 3);
			PUCHAR Candidate = Ptr + 7 + Disp;

			if (Ssdt::ValidateSsdt((PSYSTEM_SERVICE_TABLE)Candidate))
			{
				return (PSYSTEM_SERVICE_TABLE)Candidate;
			}
		}
	}

	// Strategy 2: If KiSystemCall64Shadow branches via jmp rel32 (0xE9), follow it
	for (ULONG i = 0; i < 0x300; i++)
	{
		PUCHAR Ptr = Lstar + i;
		if (!MmIsAddressValid(Ptr) || !MmIsAddressValid(Ptr + 5))
		{
			break;
		}

		if (Ptr[0] == 0xE9)
		{
			LONG JumpDisp = *(PLONG)(Ptr + 1);
			PUCHAR JumpTarget = Ptr + 5 + JumpDisp;

			if (MmIsAddressValid(JumpTarget))
			{
				for (ULONG j = 0; j < 0x2000; j++)
				{
					PUCHAR SearchPtr = JumpTarget + j;
					if (!MmIsAddressValid(SearchPtr) || !MmIsAddressValid(SearchPtr + 7))
					{
						break;
					}

					if (SearchPtr[0] == 0x4C && SearchPtr[1] == 0x8D && SearchPtr[2] == 0x15)
					{
						LONG Disp = *(PLONG)(SearchPtr + 3);
						PUCHAR Candidate = SearchPtr + 7 + Disp;

						if (Ssdt::ValidateSsdt((PSYSTEM_SERVICE_TABLE)Candidate))
						{
							return (PSYSTEM_SERVICE_TABLE)Candidate;
						}
					}
				}
			}
		}
	}

	// Strategy 3: Fallback scan through ntoskrnl.exe executable sections
	ULONG_PTR KernelBase = Ssdt::GetKernelBase(Lstar);
	if (KernelBase != 0)
	{
		PIMAGE_DOS_HEADER Dos = (PIMAGE_DOS_HEADER)KernelBase;
		PIMAGE_NT_HEADERS Nt = (PIMAGE_NT_HEADERS)(KernelBase + Dos->e_lfanew);
		PIMAGE_SECTION_HEADER Section = IMAGE_FIRST_SECTION(Nt);

		for (USHORT s = 0; s < Nt->FileHeader.NumberOfSections; s++, Section++)
		{
			if (Section->Characteristics & IMAGE_SCN_MEM_EXECUTE)
			{
				PUCHAR SecStart = (PUCHAR)(KernelBase + Section->VirtualAddress);
				ULONG SecSize = Section->Misc.VirtualSize;

				for (ULONG i = 0; i < SecSize - 7; i++)
				{
					PUCHAR Ptr = SecStart + i;
					if (Ptr[0] == 0x4C && Ptr[1] == 0x8D && Ptr[2] == 0x15)
					{
						LONG Disp = *(PLONG)(Ptr + 3);
						PUCHAR Candidate = Ptr + 7 + Disp;

						if (Ssdt::ValidateSsdt((PSYSTEM_SERVICE_TABLE)Candidate))
						{
							return (PSYSTEM_SERVICE_TABLE)Candidate;
						}
					}
				}
			}
		}
	}

	return NULL;
}
